class Widget {
public:
  // User-declared dtor suppresses implicit move operations.
  virtual ~Widget() = default;

  // Re-enable move operations by explicitly defaulting them.
  Widget(Widget&&) noexcept = default;
  Widget& operator=(Widget&&) noexcept = default;

  // Declaring moves suppresses implicit copy operations.
  // To support copying, they must also be defaulted.
  Widget(const Widget&) = default;
  Widget& operator=(const Widget&) = default;
};

// Now, Widget is both copyable and movable, as intended.
// std::is_move_constructible_v<Widget> is true.
// std::is_copy_constructible_v<Widget> is true.
